/// Returns an index of a maximum element in `a`.
/// 
/// Requirements satisfied:
/// - `a` is assumed non-empty (input size is positive).
/// - returned index is within bounds
/// - `a[max_idx] >= a[i]` for all valid `i`
/// - if multiple maxima exist, any one index is fine
pub fn find_max(a: &[i32]) -> usize {
    // Since `a` is non-empty, start with index 0 as the current best.
    let mut max_idx: usize = 0;

    // Scan remaining elements; update when we find a strictly larger value.
    for i in 1..a.len() {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
    }

    max_idx
}

